Ext.define('BNK.view.common.ApprovalLinePopupViewController', {
    extend: 'Ext.app.ViewController',
    alias: 'controller.common.approvallinepopup',

    config: {
        viewId: 'ApprovalLinePopup'
    },

    onChangeMyApprLine: function(combobox, newValue, oldValue, eOpts) {
        var me = this,
            refs = me.getReferences(),
            gridApprLine = refs.gridApprLine,
            items = combobox.getStore().data.items,
            comAprLineId = newValue.data.comAprLineId;

        for ( var i in items) {
            var data = items[i].data;
            if (data.comAprLineId === comAprLineId) {
                gridApprLine.setData(data.details);
                break;
            }
        }
    },

    /* [확인] 처리 */
    onClickedBtnOk: function(button, e, eOpts) {
        var me = this,
            refs = me.getReferences(),
            gridApprLine = refs.gridApprLine,
            records = gridApprLine.getJsonAllRecords();

        for (var i in records) {
            var record = records[i];
            record.aprDtti = null; // 결재일자
            record.dlvDtti = null; // 받은일자

            // 순번 1인 작성자인 경우, 받은일자설정
            if (record.sno === 1) {
                record.dlvDtti = DateUtils.getFormatValue(new Date(), 'Y-m-d H:i');
            }
        }

        me.getView().fireEvent('selected', records, me.getView());
    },

    /* [취소] 처리 */
    onClickedBtnCancel: function(button, e, eOpts) {
        var me = this;
        me.getView().close();
    },

    /* 초기화 처리 */
    initialize: function(component, eOpts) {
        var me = this;

        Ext.Ajax.request({
            headers : {
                serviceId : 'COMAPR0001R01M',
                viewId : 'ApprovalLinePopup'
            },
            scope : me,
            success : function(response) {
                var me = this,
                    refs = me.getReferences(),
                    vm = me.getViewModel(),
                    myApprLine = refs.myApprLine,
                    store = vm.data.ApprovalLineStore,
                    responseJson = Ext.JSON.decode(response.responseText),
                    records = responseJson.result;

                if (records && records.length > 0) {
                    store.add(records);
                    myApprLine.setValue(store.getAt(0).get('comAprLineId'));	// 첫행선택
                }
            }
        });
    }

});